<script setup>
import { h, defineComponent, markRaw, ref, onMounted, onBeforeUnmount, nextTick } from 'vue';
import DockWorkspace from 'capsule-ui-kit/DockWorkspace';
import CapsulePanel from 'capsule-ui-kit/CapsulePanel';
import { resolveCapsuleType } from './capsuleTypes.js';
const props = defineProps({ layout: {type: /** @type {import('vue').PropType<import('capsule-ui-kit/layout').LayoutProfileEnvelope>} */ (Object),required:true}, storage:{type: /** @type {import('vue').PropType<{readRaw:()=>Promise<string|null>,writeAtomic:(json:string)=>Promise<void>}>} */ (Object),required:true}, scope:{type: /** @type {import('vue').PropType<import('capsule-ui-kit/layout').LayoutProfileScope>} */ (Object),required:true} });
const scheme=ref('dark'), settled=ref(false), palette=ref(false), query=ref('');
const search=ref(/** @type {HTMLInputElement|null} */ (null)); let invoker=/** @type {HTMLElement|null} */(null);
function toggleScheme() { scheme.value=scheme.value==='dark'?'light':'dark'; document.documentElement.dataset.themeScheme=scheme.value; }
async function openPalette() { invoker=/** @type {HTMLElement|null} */ (document.activeElement); palette.value=true; query.value=''; await nextTick(); search.value?.focus(); }
function closePalette() { palette.value=false; invoker?.focus(); }
/** @param {KeyboardEvent} event */
function keyboard(event) { if ((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k') {event.preventDefault();openPalette();} if(event.key==='Escape'&&palette.value) closePalette(); }
/** @param {KeyboardEvent} event */
function trap(event) { if (!(event.currentTarget instanceof HTMLElement) || !document.activeElement) return; const controls=Array.from(/** @type {NodeListOf<HTMLElement>} */ (event.currentTarget.querySelectorAll('input,button'))); if(event.key==='Tab') { const i=controls.indexOf(/** @type {HTMLElement} */ (document.activeElement)); event.preventDefault(); controls[(i+(event.shiftKey?-1:1)+controls.length)%controls.length]?.focus(); } }
const CapsuleRouter=markRaw(defineComponent({name:'CapsuleRouter',props:{params:{type:Object,required:true}},setup(routerProps) {return ()=>{ const id=routerProps.params?.params?.capsuleId; const api=routerProps.params?.api; let surface; try {surface=h(resolveCapsuleType(id));} catch {surface=h('p',{role:'alert'},'Unknown capsule type. Reset the workspace layout.');} return h(CapsulePanel,{capsuleId:id,placeholderTitle:api?.title??id,presentationInstance:api?.id??id,onClosePanel:()=>api?.close?.()},{surface:()=>surface});};}}));
const panelComponents=markRaw({CapsulePanel:CapsuleRouter});
function ready() { settled.value=true; console.log('CAPSULE_STARTER_READY'); }
onMounted(()=>window.addEventListener('keydown',keyboard)); onBeforeUnmount(()=>window.removeEventListener('keydown',keyboard));
</script>
<template><div class="starter" :data-wall-settled="String(settled)">
<header><div><strong>Capsule workspace</strong><span class="subtitle">Your tools, in place</span></div><nav aria-label="Workspace controls"><button id="command-palette-open" data-semantic-anchor="workspace/commands" aria-haspopup="dialog" @click="openPalette">Commands <kbd>Ctrl K</kbd></button><button id="theme-toggle" data-semantic-anchor="workspace/theme" @click="toggleScheme">{{scheme==='dark'?'Use light theme':'Use dark theme'}}</button></nav></header>
<main aria-label="Starter workspace"><DockWorkspace :scope="scope" :default-profile="layout" :storage="storage" :panel-components="panelComponents" :color-scheme="scheme" workspace-title="Starter wall" @wall-settled="ready" /></main>
<footer role="status">{{settled?'Workspace ready.':'Opening workspace…'}} <span>F6 switches groups · Drag tabs to arrange</span></footer>
<div v-if="palette" class="veil" @click.self="closePalette"><section role="dialog" aria-modal="true" aria-labelledby="command-title" class="palette" @keydown="trap"><h2 id="command-title">Commands</h2><label for="command-search">Find a command</label><input id="command-search" ref="search" v-model="query" /><button v-if="'toggle theme'.includes(query.toLowerCase())" @click="toggleScheme();closePalette()">Toggle theme</button><button @click="closePalette">Close commands</button></section></div></div></template>
<style>
*{box-sizing:border-box}body{margin:0;font-family:var(--cuk-semantic-typography-font-family-sans,system-ui);color:var(--cuk-semantic-text-primary,#e2e8f0);background:var(--cuk-semantic-surface-canvas,#0f172a)}
.starter{height:100dvh;display:grid;grid-template-rows:auto minmax(0,1fr) auto}header{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:14px 20px;border-bottom:1px solid var(--cuk-semantic-border-default,#475569)}header strong{font-size:18px;letter-spacing:-.02em}.subtitle{display:block;font-size:12px;opacity:.75;margin-top:3px}nav{display:flex;gap:8px}main{min-height:0;min-width:0}footer{padding:8px 20px;font-size:12px;display:flex;justify-content:space-between;border-top:1px solid var(--cuk-semantic-border-default,#475569)}button,input{font:inherit;color:inherit;background:var(--cuk-semantic-surface-panel,#1e293b);border:1px solid var(--cuk-semantic-border-default,#64748b);border-radius:4px;padding:8px 12px}button{cursor:pointer}button:disabled{cursor:default;opacity:.6}button:focus-visible,input:focus-visible{outline:2px solid var(--cuk-semantic-focus-ring-color,#60a5fa);outline-offset:2px}kbd{font-size:11px;margin-left:12px}h2{font-size:20px}.example{padding:24px;max-width:720px}.example form{display:grid;gap:10px}.terminal-example{height:100%;display:flex;flex-direction:column}.terminal-example>p{padding:8px 12px;font-size:12px}.terminal-example>.cui-terminal-view{flex:1}.veil{position:fixed;inset:0;background:#080d1acc;display:grid;place-items:start center;padding-top:15vh;z-index:1000}.palette{width:min(500px,90vw);display:grid;gap:12px;padding:24px;background:var(--cuk-semantic-surface-canvas,#0f172a);border:1px solid var(--cuk-semantic-border-default,#64748b);border-radius:8px}@media(max-width:640px){header{flex-wrap:wrap}footer span{display:none}}
</style>
